/bin/bash -lc "clickhouse-client --multiquery <<'SQL'
CREATE DATABASE IF NOT EXISTS analytics;
CREATE TABLE IF NOT EXISTS analytics.raw_events (
    event_id String,
    event_ts DateTime,
    payload String
)
ENGINE = MergeTree
PARTITION BY toMonth(event_ts)
ORDER BY (event_ts, event_id)
TTL event_ts + INTERVAL 90 DAY;
SHOW CREATE TABLE analytics.raw_events;
SQL"

